import React, { useState, useEffect } from "react";
import './App.css';

const sortTasksByDueDate = (tasks) => {
  return tasks.slice().sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));
};

function App() {
  const [tasks, setTasks] = useState([]);

  // Fetch data from SWAPI on page load
  useEffect(() => {
    const fetchSWAPITasks = async () => {
      try {
        const response = await fetch("https://swapi.py4e.com/api/people/"); // SWAPI endpoint
        const data = await response.json();
        
        // Map the fetched data to a task-like structure
        const swapiTasks = data.results.map((person, index) => ({
          id: `swapi-${index}`, // Unique ID for these tasks
          name: person.name, // Use the name of the Star Wars character
          description: `Height: ${person.height}, Mass: ${person.mass}`, // Example description
          dueDate: new Date().toISOString().split("T")[0], // Use today's date
        }));

        // Prepopulate tasks with SWAPI data
        setTasks(swapiTasks);
      } catch (error) {
        console.error("Error fetching SWAPI data:", error);
      }
    };

    fetchSWAPITasks();
  }, []); // Empty dependency array means this runs once on app load

  const handleFormSubmit = (e) => {
    e.preventDefault();
    const taskName = e.target.taskName.value.trim();
    const taskDescription = e.target.taskDescription.value.trim();
    const taskDueDate = e.target.taskDueDate.value;

    if (!taskName || !taskDescription || !taskDueDate) {
      alert("All fields are required");
      return;
    }

    const newTask = {
      id: Date.now(),
      name: taskName,
      description: taskDescription,
      dueDate: taskDueDate,
    };

    setTasks((prevTasks) => [...prevTasks, newTask]);
    e.target.reset();

    const modal = document.getElementById("createTask");
    modal.style.display = "none";
  };

  const openModal = () => {
    const modal = document.getElementById("createTask");
    modal.style.display = "flex";
  };

  const closeModal = () => {
    const modal = document.getElementById("createTask");
    modal.style.display = "none";
  };

  return (
    <div className="App">
      <h1>PyTasks</h1>
      <button id="openPopUp" onClick={openModal}>Create a Task</button>

      <div id="createTask" className="modal">
        <div className="modal-content">
          <span className="close" onClick={closeModal}>&times;</span>
          <form id="taskForm" onSubmit={handleFormSubmit}>
            <label htmlFor="taskName">Task Name</label>
            <input type="text" id="taskName" name="taskName" required />

            <label htmlFor="taskDescription">Task Description</label>
            <textarea id="taskDescription" name="taskDescription" required></textarea>

            <label htmlFor="taskDueDate">Due Date</label>
            <input type="date" id="taskDueDate" name="taskDueDate" required />

            <button type="submit">Add Task</button>
          </form>
        </div>
      </div>

      <div className="task-list">
        {sortTasksByDueDate(tasks).map((task) => (
          <div key={task.id} className="task-item">
            <h3>{task.name}</h3>
            <p>{task.description}</p>
            <p><strong>Due:</strong> {task.dueDate}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
